def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([1]), fmt([2]), fmt([2, 0]), fmt([1, 0]), fmt([2, 1]), fmt([0, 1, 2]), fmt([2, 1, 0]),
             fmt([2, 0, 2, 1, 1, 0]), fmt([1, 1, 1, 1]), fmt([2, 2, 0, 0, 1, 1, 2, 0])]
    for _ in range(24):
        n = rng.randint(1, 30)
        tests.append(fmt([rng.randint(0, 2) for _ in range(n)]))
    N = 300000
    tests.append(fmt([rng.randint(0, 2) for _ in range(N)]))
    tests.append(fmt([2] * (N // 3) + [1] * (N // 3) + [0] * (N - 2 * (N // 3))))
    tests.append(fmt([rng.choice([0, 2]) for _ in range(N)]))
    return tests
